### Summary

In `contracts/passkey-signer/src/` (`lib.rs`, `registry.rs`, `cbor.rs`, and `frontend/lib/passkey.ts`), `PasskeySigner::verify_and_record` records consumed WebAuthn challenge nonces under a global unscoped key `RegistryKey::UsedChallenge(BytesN)`, checks replay after ECDSA signature verification instead of before, omits WebAuthn `origin` verification and structural JSON key-context parsing in `find_json_string_value`, and uses a Naive CBOR byte substring scan (`findCoseByteString`) in `extractP256KeyFromAuthData` that can match `0x21 0x58 0x20` inside raw X coordinate bytes.

### Reproduction

```rust
// Run: cargo test -p passkey-signer poc_verify_and_record_unscoped_nonce_and_cbor_spoofing
#[test]
fn poc_verify_and_record_unscoped_nonce_and_cbor_spoofing() {
    let env = new_env();
    let (contract_id, client) = deploy(&env);
    let alice = Address::generate(&env);
    let bob = Address::generate(&env);
    let rp_id_hash = [0x11u8; 32];
    let (x, y) = fake_pub_key();

    client.register(
        &alice,
        &to_bytes32(&env, &rp_id_hash),
        &to_bytes32(&env, &x),
        &to_bytes32(&env, &y),
        &0u32,
    );
    client.register(
        &bob,
        &to_bytes32(&env, &rp_id_hash),
        &to_bytes32(&env, &x),
        &to_bytes32(&env, &y),
        &0u32,
    );

    // 1. Unscoped challenge nonce: Alice consuming challenge C blocks Bob on the same challenge C
    //    and `is_nonce_used(C)` cannot distinguish whether Alice or an attacker consumed C.
    let challenge = to_bytes32(&env, &[0x42u8; 32]);
    env.as_contract(&contract_id, || {
        crate::registry::record_challenge(&env, &challenge).unwrap();
    });
    assert!(client.is_nonce_used(&challenge));

    // 2. Substring key spoofing in cbor::find_json_string_value:
    //    A first field whose value contains escaped or nested `"type":"webauthn.get"`
